create or replace function public.validate_coupon(p_code text,p_order_amount numeric) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$ declare c public.coupons%rowtype;v_discount numeric;begin select * into c from public.coupons where code=trim(p_code) and is_active and (starts_at is null or starts_at<=now()) and (expires_at is null or expires_at>=now());if c.id is null then return jsonb_build_object('valid',false,'error','Invalid or expired coupon');end if;if p_order_amount<coalesce(c.minimum_order_amount,0) then return jsonb_build_object('valid',false,'error','Minimum order amount not met');end if;if c.usage_limit is not null and c.used_count>=c.usage_limit then return jsonb_build_object('valid',false,'error','Coupon usage limit reached');end if;v_discount:=case when c.discount_type='percentage' then least(p_order_amount*c.discount_value/100,coalesce(c.maximum_discount_amount,p_order_amount)) else least(c.discount_value,p_order_amount) end;return jsonb_build_object('valid',true,'coupon_id',c.id,'code',c.code,'discount_amount',round(v_discount,2));end$$;
revoke execute on function public.validate_coupon(text,numeric) from anon;grant execute on function public.validate_coupon(text,numeric) to authenticated;